+    const index = await fs.readFile(path.join(outputDir, 'index.html'), 'utf8');
+
+    expect(pages).toEqual([]);
+    expect(index).toContain('<h1>Pages</h1>');
+  });
+
+  test('reports a missing content directory', async () => {
